#define GB_FONT_COUNT 46

static inline const uint8_t* gb_font_lookup(uint16_t code) {
    int lo = 0, hi = GB_FONT_COUNT - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (gb_font_table[mid].gb == code) return gb_font_table[mid].data;
        if (code < gb_font_table[mid].gb) hi = mid - 1;
        else lo = mid + 1;
    }
    return NULL;
}